import{_ as e,c as l,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"风山渐","description":"周易折中 - 风山渐","frontmatter":{"title":"风山渐","description":"周易折中 - 风山渐"},"headers":[],"relativePath":"zh/classics/zhezhong/059.md","filePath":"zh/classics/zhezhong/059.md"}'),i={name:"zh/classics/zhezhong/059.md"};function n(d,a,p,t,s,o){return r(),l("div",null,[...a[0]||(a[0]=[h('<h1 id="风山渐" tabindex="-1">风山渐 <a class="header-anchor" href="#风山渐" aria-label="Permalink to “风山渐”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈渐〉：“序卦：艮者止也，物不可以终止，故受之以渐。渐者进也，止必有进，屈伸消息之理也。止之所生，亦进也；所反，亦进也。渐所以次艮也。进以序为渐，今人以缓进为渐，进以序不越次，所以缓也。为卦上巽下艮，山上有木，木之高而因山，其高有因也；其高有因，乃其进有序也，所以为渐也。”</p><p>渐：女归吉，利贞</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>渐渐进也。为卦止于下而巽于上，为不遽进之义，有女归之象焉。又自二至五位皆得正，故其占为“女归吉”，而又戒以“利贞”也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>以卦才兼渐义而言也。乾坤之变为巽艮，巽艮重而为渐。在渐体而言，中二爻交也，由二爻之交，然后男女各得正位。初终二爻虽不当位，亦阳上阴下，得尊卑之正。男女各得其正，亦得位也。与归妹正相对，女之归能如是之正，则吉也。天下之事，进必以渐者，莫如女归。臣之进于朝，人之进于事，固当有序。不以其序，则陵节犯义，凶咎随之。然以义之轻重，廉耻之道，女之从人最为大也，故以女归为义。且男女万事之先也，诸卦多有利贞，而所施或不同。有渉不正之疑而为之戒者，有其事必贞乃得其宜者，有言所以利者以其有贞也。所谓渉不正之疑而为之戒者，损之九二是也。处阴居说，故戒以宜贞也。有其事必贞乃得宜者，大畜是也。言所畜利于贞也。有言所以利者以其有贞者，渐是也。言女归之所以吉，利于如此贞正也。盖其固有，非设戒也。渐之义宜能亨，而不云亨者，盖亨者通逹之义，非渐进之义也。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏瑗曰 ：天下万事莫不有渐，然于女子尤湏有渐。何则？女子处于闺门之内，必湏男子之家问名、纳采、请期，以至于亲迎，其礼毕备，然后乃盛其礼而正夫妇之道。君子之人处穷贱不可以干时邀君，急于求进；处于下位者不可谄谀佞媚以希高位，皆由渐而致之，乃获其吉也。</p></li><li><p>郭氏雍曰 ：进之渐者无若女之归。女归不以渐，则奔也。渐则为归，速则为奔，故女归以渐为吉。凡天下之进如女归之渐，无不吉也。利贞者，女归之道正，固守之无不利也。</p></li><li><p>胡氏炳文曰 ：咸取女吉，取者之占也；渐女归吉，嫁者之占也。然皆以贞艮为主。艮止也，止而说则其感也以正，是为取女之吉；止而巽则其进也以正，是为女归之吉。</p></li></ul><p>象曰：山上有木，渐。君子以居贤德善俗</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>二者皆当以渐而进，疑“贤”字衍或“善”下有脱字。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>山上有木，其高有因，渐之义也。君子观渐之象，以居贤善之德，化美于风俗。人之进于贤德，必有其渐，习而后能安，非可陵节而遽至也。在己且然，教化之于人，不以渐其能入乎？移风易俗非一朝一夕所能成，故善俗必以渐也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏曰 ：地中生木，以时而升；山上有木，其进以渐。</p></li><li><p>冯氏当可曰 ：居积也。德以渐而积，俗以渐而善。内卦艮止，居德者止诸内也；外卦巽入，善俗者入于外也。体艮以居德，体巽以善俗。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>地中生木，始生之木也；山上有木，高大之木也。凡木始生，枝条骤长，旦异而夕不同；及既高大，则自拱把而合抱，自捩手而干霄，必须逾年积岁。此升与渐之义所以异也。居德善俗皆须以渐，又居贤德然后可以善俗，亦渐之意也。</p><p>彖曰：渐，之进也，女归吉也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>之字疑衍，或是渐字。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>如渐之义而进，乃女归之吉也。谓正而有渐也，女归为大耳，它进亦然。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>郭氏雍曰 ：传言“渐之进如女之归则吉”，所以明卦辞也。盖世俗多失渐进之道，独女归有渐存焉耳。</p></li><li><p>毛氏璞曰 ：易未有一义明两卦者，晋进也，渐亦进，何也？渐非进以渐而进耳。案曰：渐之进也，以别于晋之进、升之进也。</p></li></ul><p>进得位，往有功也；进以正，可以正邦也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以卦变释利贞之意。盖此卦之变自涣而来，九进居三；自旅而来，九进居五，皆为得位之正。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>渐进之时，而阴阳各得正位，进而有功也。四复由上进而得正位，三离下而为上遂得正位，亦为进得位之义。以正道而进，可以正邦国至于天下也。凡进于事、进于德、进于位，莫不皆当以正也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li>梁氏寅曰 ：卦自二至五阴阳各得正位，此所以进而有功也。进得位以位言，进以正以道言。案梁氏之说得之，盖进得位以卦位言，进以正以人事言。在卦为得位者，在人事即是得正也。正邦亦只是申有功之意。易卦中四爻得位者，既济曰“定也”，家人曰“正家而天下定矣”，蹇、渐皆曰“以正邦也”，盖董子“正朝廷以正百官，正百官以正万民”之意也。</li></ul><p>其位刚得中也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>以卦体言，谓九五。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>上云“进得位，往有功也”，统言阴阳得位是以进而有功。复云“其位刚得中也”，所谓位者五，以刚阳中正得尊位也。诸爻之得正亦可谓之得位矣，然未若五之得尊位，故特言之。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>梁氏寅曰 ：上言“进得位”以自二至五四爻言之也，此又言“其位刚得中”以九五言之也。</li></ul><p>止而巽，动不穷也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>以卦德言，渐进之义。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>内艮止，外巽顺。止为安静之象，巽为和顺之义。人之进也，若以欲心之动，则躁而不得其渐，故有困穷。在渐之义，内止静而外巽顺，故其进动不有困穷也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>吴氏曰 ：慎曰“止而巽终是进”，但进以渐，故卦名为渐。若巽而止，则终于止而事壊乱矣，故卦名为蛊。内外先后之辨，不可易也。</li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>刚得中，止而巽，又就中四爻内特举九五与卦德，申女归利贞之义。节卦说以行险当位中正同。</p><p>初六：鸿渐于干，小子厉有言，无咎</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>鸿之行有序而进有渐，干水涯也。始进于下，未得所安，而上复无应，故其象如此。而其占则为小子厉，虽有言而于义则无咎也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>渐诸爻皆取鸿象。鸿之为物，至有时而群有序，不失其时序，乃为渐也。干，水湄，水鸟止于水之湄，水至近也，其进可谓渐矣。行而以时，乃所谓渐进，不失渐得其宜矣。六居初，至下也，阴之才至弱也，而上无应援，以此而进，常情之所忧也。君子则深识远照，知义理之所安，时事之所宜，处之不疑。小人幼子，唯能见已然之事，从众人之知，非能烛理也，故危惧而有言。盖不知在下所以有进也，用柔所以不躁也，无应所以能渐也，于义自无咎也。若渐之初而用刚急进，则失渐之义，不能进而有咎必矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li>李氏鼎祚曰 ：鸿随阳鸟，喻女从夫。卦明渐义，爻皆称焉。</li></ul><p>李氏鼎祚曰 ：鸿随阳鸟，喻女从夫。卦明渐义，爻皆称焉。</p><ul><li>杨氏简曰 ：进欲其知时，故鸿为象。进欲其渐，故以干、磐、陆、木、陵为象。</li></ul><p>杨氏简曰 ：进欲其知时，故鸿为象。进欲其渐，故以干、磐、陆、木、陵为象。</p><ul><li>何氏楷曰 ：六爻皆取鸿象，往来有时，先后有序，于渐之义为切也。昏礼用雁，取不再偶，又于女归之义为切也。</li></ul><p>何氏楷曰 ：六爻皆取鸿象，往来有时，先后有序，于渐之义为切也。昏礼用雁，取不再偶，又于女归之义为切也。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>昏礼用雁，大夫执贽亦用雁，皆取有别有序之义。此爻“小子厉有言”，正如晋之“摧如”，凡始进之初，未有便得所安而人信之者。然正惟如此，乃所以安其身而信于人。若谋便于身图而求合于众议，则危疑之大者至矣。惟升之初六曰“众允”，盖以其为卦主，时义不同也。</p><p>象曰：小子之厉，义无咎也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>虽小子以为危厉，在义理实无咎也。</p><p>六二：鸿渐于磐，饮食衎衎，吉</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>磐，大石也。渐远于水，进于干而益安矣。衎衎，和乐意。六二柔顺中正，进以其渐而上有九五之应，故其象如此而占则吉也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>二居中得正，上应于五，进之安裕者也。但居渐，故进不速。磐石之安平者，江河之滨所有，象进之安。自干之磐，又渐进也。二与九五之君以中正之道相应，其进之安固平易莫加焉，故其饮食和乐，衎衎然，吉可知也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：艮为石，故有磐象。鸿食则呼众，饮食衎衎，和鸣。初之小子厉有言，危而伤也；二饮食衎衎，安且乐矣。时使之然也。在初则无应，在二则柔顺中正而上有九五之应也。</li></ul><p>象曰：饮食衎衎，不素饱也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>素饱如诗言“素餐”，得之以道，则不为徒饱而处之安矣。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>爻辞以其进之安平，故取饮食和乐为言。夫子恐后人之未喻，又释之云：中正君子遇中正之主，渐进于上，将行其道以及天下。所谓“饮食衎衎”，谓其得志和乐，不谓空饱饮食而已，素空也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏焕曰 ：二以中正应五而得禄，非尸位素餐者比，故食之衎衎而乐也。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>六爻以鸿取进象，自水涯以至山上，自远而近，自下而高也。干为最远，是士之将进而不苟进者。故在《诗经》曰：“置之河之干兮，彼君子兮，不素餐兮。”二虽进为时用，渐于磐矣，而不忘“不素餐”之义，所谓达不变塞者也。</p><p>九三：鸿渐于陆，夫征不复，妇孕不育，凶；利御寇</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>鸿，水鸟，陆非所安也。九三过刚不中而无应，故其象如此。而其占，夫征则不复，妇孕则不育，凶莫甚焉。然以其过刚也，故利御寇。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>平高曰陆，平原也。三在下卦之上，进至于陆也。阳上进者也，居渐之时，志将渐进而上无应援，当守正以俟时。安处平地则得渐之道，若或不能自守，欲有所牵志，有所就，则失渐之道。四阴在上而密比，阳所说也；三阳在下而相亲，阴所从也。二爻相比而无应，相比则相亲而易合，无应则无适而相求，故为之戒。夫，阳也，谓三。三若不守正而与四合，是知征而不知复。征，行也；复，反也。不复谓不反顾义理。妇谓四，若以不正而合，则虽孕而不育，盖非其道也，如是则凶也。三之所利，在于御寇。非理而至者，寇也。守正以闲邪，所谓御寇也。不能御寇，则自失而凶矣。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>郭氏雍曰 ：以卦辞言“女归吉”，故以夫妇为言。</li></ul><p>郭氏雍曰 ：以卦辞言“女归吉”，故以夫妇为言。</p><ul><li>程氏敬承曰 ：三以过刚之资，当渐进之时，惧其进而犯难也，故有戒辞焉。征、孕皆凶，言不可进也；利在御寇，言可止也。</li></ul><p>程氏敬承曰 ：三以过刚之资，当渐进之时，惧其进而犯难也，故有戒辞焉。征、孕皆凶，言不可进也；利在御寇，言可止也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此卦以女归为义，则必阴阳相应乃与义合。故初之厉者无应也，二之安者有应也，三亦无应而位愈高，则不止于厉而已。上九在卦外，不与三应，如夫征而不复，不顾其家也。三刚质失柔道，如妇有产孕而不能养育，不恤其子也。以士君子之进言，之上不下交，而下又失顺勤之道，于义则凶矣。上下不交，必有谗邪闲于其闲，所谓寇也。惟能谨慎自守，使寇无所乘，则可以救其过刚之失而利。</p><p>象曰：夫征不复，离群丑也；妇孕不育，失其道也。利用御寇，顺相保也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>夫征不复，则失渐之正，从欲而失正，离判其群类，为可丑也。卦之诸爻，皆无不善，若独失正，是离其群类。妇孕不由其道，所以不育也。所利在御寇，谓以顺道相保。君子之与小人比也，自守以正，岂唯君子自完其己而已乎？亦使小人得不陷于非义，是以顺道相保，御止其恶，故曰“御寇”。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏简曰 ：夫征不复，上九不应，离群丑也；妇孕不育，九三失其所以为妇也。三不中有失道之象，故凶。非正者足以害我，故曰“寇”。虑三之失道或亲于寇而不能御也，故教之御寇，则我不失于正，顺而夫妇可以相保矣。</p></li><li><p>熊氏良辅曰 ：顺相保，顺愼通用，只是谨愼以相保守也。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>杨氏之说，爻义文意两得之矣。君子之仕也，上虽不交，而已必尽其道。故周公曰：“恩斯勤斯，育子之闵斯，不可以不遇而遂弃其殷勤也。”王仲淹曰：“美哉公旦之为周也，必使我君臣相安而祸乱不作。”其顺相保之谓乎？</p><p>六四：鸿渐于木，或得其桷，无咎</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>鸿不木栖，桷平柯也。或得平柯，则可以安矣。六四乘刚而顺巽，故其象如此。占者如之，则无咎也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>当渐之时，四以阴柔进据刚阳之上，阳刚而上进，岂能安处阴柔之下？故四之处非安地，如鸿之进于木也。木渐高矣，而有不安之象。鸿趾连不能握枝，故不木栖。桷，横平之柯，唯平柯之上乃能安处。谓四之处本危，或能自得安宁之道，则无咎也。如鸿之于木，本不安，或得平柯而处之，则安也。四居正而巽顺，宜无咎者也。必以得失言者，因得失以明其义也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>房氏乔曰 ：进而渐于木，失所也。或得劲直之桷，可容网足而安栖，谓上附于五，故无咎。</li></ul><p>房氏乔曰 ：进而渐于木，失所也。或得劲直之桷，可容网足而安栖，谓上附于五，故无咎。</p><ul><li>胡氏炳文曰 ：巽为木，而处艮山之上，鸿渐于此则愈高矣。鸿之掌不能握木，木虽高非鸿所安也。然阴居阴得正，如于木之中或得平柯而处之，则亦安矣，故无咎。</li></ul><p>胡氏炳文曰 ：巽为木，而处艮山之上，鸿渐于此则愈高矣。鸿之掌不能握木，木虽高非鸿所安也。然阴居阴得正，如于木之中或得平柯而处之，则亦安矣，故无咎。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>六四亦无应者也，然六四承九五，例皆吉者，以阴承阳，合于女归之义矣。顺以事上，高而不危，故有集木得桷之象。</p><p>象曰：或得其桷，顺以巽也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>桷者，平安之处。求安之道，唯顺与巽。若其义顺正，其处卑巽，何处而不安？如四之顺正而巽，乃得桷也。</p><p>九五：鸿渐于陵，妇三岁不孕，终莫之胜，吉</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>陵，高阜也。九五居尊，六二正应在下，而为三四所隔，然终不能夺其正也。故其象如此，而占者如是则吉也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>陵，高阜也，鸿之所止最高处也，象君之位。虽得尊位，然渐之时，其道之行固亦非遽。与二为正应，而中正之德同，乃隔于三四。三比二，四比五，皆隔其交者也。未能即合，故三岁不孕。然中正之道有必亨之理，不正岂能隔害之？故终莫之能胜，但其合有渐耳，终得其吉也。以不正而敌中正，一时之为耳，久其能胜乎？</p><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>此卦之爻象与归妹同，不择阴爻阳爻皆有妇象也。先儒见三五两阳爻皆言妇，故于三则以妇指四，于五则以妇指二。今推爻意，盖三五皆取妇象。三无应者也，五虽有应而反其类者也。既取妇象而所应者阴，是之谓反类。其失卦义，又有甚于无应者矣。故三犹孕也，但不育耳；五则三岁不孕，盖不相和合之甚者也。三过刚，故戒以御寇，恐其不能慎也；五有中正之德，故无戒辞，而直以“终莫之胜”决之。胜字蒙九三“御寇”之义。夫谗邪，国之寇也。君子之进所以不能和合而通者，寇胜之也。然如九五之德，则所谓可以正邦者，当渐之时，有终吉之理，岂谗邪所能胜哉？</p><p>象曰：终莫之胜，吉，得所愿也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>君臣以中正相交，其道当行，虽有闲其闲者，终岂能胜哉？徐必得其所愿，乃渐之吉也。</p><p>上九：鸿渐于陆，其羽可用为仪，吉</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>胡氏、程氏皆云“陆”当作“逵”，谓云路也。今以韵读之，良是。仪，羽旄旌纛之饰也。上九至高，出乎人位之外，而其羽毛可用以为仪饰。盖虽极高而不为无用之象，故其占为如是则吉也。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>安定胡公以“陆”为“逵”，“逵”云路也，谓虚空之中。《尔雅》九达谓之“逵”，“逵”通逹无阻蔽之义也。上九在至高之位，又益上进，是出乎位之外。在它时则为过矣，于渐之时，居巽之极，必有其序，如鸿之离所止而飞于云空，在人则超逸乎常事之外者也。进至于是而不失其渐，贤逹之高致也，故可用为仪法而吉也。羽，鸿之所用进也，以其进之用况上九进之道也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖达曰 ：上九与三皆处卦上，故并称陆。上九最居上极，是进处高洁，故曰“鸿渐于陆”也。其羽可用为仪吉者，居无位之地，是不累于位者也。处高而能不以位自累，则其羽可用为物之仪表，可贵可法也。</li></ul><p>孔氏颖达曰 ：上九与三皆处卦上，故并称陆。上九最居上极，是进处高洁，故曰“鸿渐于陆”也。其羽可用为仪吉者，居无位之地，是不累于位者也。处高而能不以位自累，则其羽可用为物之仪表，可贵可法也。</p><ul><li>王氏安石曰 ：其进也以渐而不失时，其翔也以群而不失序，所谓进退可法者也。</li></ul><p>王氏安石曰 ：其进也以渐而不失时，其翔也以群而不失序，所谓进退可法者也。</p><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>六爻皆有女归之义，独于三五言妇者，阴爻则其为臣道妻道不必言也。上九又处卦上，以为妻道则女之已老而非归者，以为臣道则臣之已退而非进者。既在卦义之外，则亦不必言也。惟三与五既居高位，又为阳爻，疑其无妇象也，故称妇焉。盖虽五位亦时以臣道妻道言，各随其卦义而已。初以阴应阴，三以阳应阳，皆不合女归之义，故各有凶厉之辞。五应二，阴阳相求者也，然以二为女，则归于阳为正耦，故饮食衎衎而和也；以五为女，则归于二为反类，故三岁不孕而不和也。四则虽无应而承五，亦得所归，可以无咎。上卦之终也，进之极也，既无所取于归与进之义，则反以无应为宜。盖在家为保姆，在国为黎老，超然于进退之外者也。“陆”字与九三重，故先儒改作“逵”字以叶韵，然“逵”、“仪”古韵实非叶也。意者“陆”乃“阿”字之误，“阿”大陵也，进于陵则阿矣。“仪”古读俄，正与“阿”叶。《诗》云：“菁菁者莪，在彼中阿。既见君子，乐且有仪。”</p><p>象曰：其羽可用为仪，吉，不可乱也</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>渐进愈高而不为无用，其志卓然，岂可得而乱哉？</p><h3 id="程传-18" tabindex="-1">程传 <a class="header-anchor" href="#程传-18" aria-label="Permalink to “程传”">​</a></h3><p>君子之进，自下而上，由微而著，跬步造次，莫不有序。不失其序，则无所不得其吉。故九虽穷高而不失其吉，可用为仪法者，以其有序而不可乱也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>胡氏炳文曰 ：二居有用之位，有益于人之国家，而非素饱者；上在无用之地，亦足为人之仪表，而非无用者。二志不在温饱，上志卓然不可乱，士大夫之出处，于此当有取焉。</p></li><li><p>张氏振渊曰 ：志虑高洁，而功名富贵不足以累其心，故其志可则。使志可得而乱，又安可用为仪哉？</p></li></ul>',145)])])}const m=e(i,[["render",n]]);export{b as __pageData,m as default};
